import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"17. 变量的范围和生命周期","description":"The Little Book of C 中文版 — 17. 变量的范围和生命周期","frontmatter":{"title":"17. 变量的范围和生命周期","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","02-语言基础","中文"],"description":"The Little Book of C 中文版 — 17. 变量的范围和生命周期","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":17,"sidebarWeight":17,"alternateZh":"/posts/c教程/zh-CN/02-语言基础/017-Scope and Lifetime of Variables","alternateEn":"/posts/c教程/en-US/02-Language Basics/017-Scope and Lifetime of Variables"},"headers":[],"relativePath":"posts/c教程/zh-CN/02-语言基础/017-Scope and Lifetime of Variables.md","filePath":"posts/c教程/zh-CN/02-语言基础/017-Scope and Lifetime of Variables.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/02-语言基础/017-Scope and Lifetime of Variables.md"};function i(l,a,o,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/02-Language Basics/017-Scope and Lifetime of Variables)</p><p>C 中的每个变量都存在于特定的范围内（可以访问它）并且具有生命周期（它在内存中存在多长时间）。了解两者对于避免常见错误（从名称冲突到神秘的“垃圾值”）至关重要。一旦你知道变量在哪里以及如何存在，你就会开始像编译器一样思考。</p><h4 id="变量范围" tabindex="-1">变量范围 <a class="header-anchor" href="#变量范围" aria-label="Permalink to &quot;变量范围&quot;">​</a></h4><p>范围定义了在代码中可以看到或使用变量的位置。</p><p>块作用域（局部变量）在函数或块内声明<code>{ ... }</code>。只能在该块内访问。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void example(void) {</span></span>
<span class="line"><span>    int x = 10;  // local to this function</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>您无法访问<code>x</code>之外<code>example()</code>.</p><p>文件范围（全局变量） 在所有函数之外声明。声明后可在文件中的任何位置访问。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int counter = 0; // global variable</span></span>
<span class="line"><span>void increment(void) {</span></span>
<span class="line"><span>    counter++;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>函数参数范围 参数的行为类似于局部变量，仅在函数内可见。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void greet(const char *name) {</span></span>
<span class="line"><span>    printf(&quot;Hello, %s!\\n&quot;, name);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>块阴影 内部变量可以暂时“隐藏”外部变量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 5;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int x = 10;  // shadows the outer x</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x); // prints 10</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x); // prints 5</span></span></code></pre></div><h4 id="可变寿命" tabindex="-1">可变寿命 <a class="header-anchor" href="#可变寿命" aria-label="Permalink to &quot;可变寿命&quot;">​</a></h4><p>生命周期决定了变量在内存中保留的时间。</p><p>自动（默认） 局部变量在函数启动时创建，在函数结束时销毁。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void demo(void) {</span></span>
<span class="line"><span>    int temp = 42;  // exists only while demo() runs</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>静态声明与<code>static</code>关键字，它们在函数调用之间保留其值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void counter(void) {</span></span>
<span class="line"><span>    static int count = 0;  // initialized only once</span></span>
<span class="line"><span>    count++;</span></span>
<span class="line"><span>    printf(&quot;Count: %d\\n&quot;, count);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>每次致电<code>counter()</code>增加相同的变量。</p><p>动态使用手动创建<code>malloc()</code>或者<code>calloc()</code>，他们会一直活到你<code>free()</code>他们。 （您将在第 3 章中了解到这一点。）</p><p>在整个计划期间全局存在。</p><h4 id="c-中的存储类" tabindex="-1">C 中的存储类 <a class="header-anchor" href="#c-中的存储类" aria-label="Permalink to &quot;C 中的存储类&quot;">​</a></h4><table tabindex="0"><thead><tr><th>关键词</th><th>存储</th><th>范围</th><th>终身</th><th>笔记</th></tr></thead><tbody><tr><td><code>auto</code></td><td>堆栈</td><td>块</td><td>函数调用</td><td>当地人的默认设置</td></tr><tr><td><code>register</code></td><td>CPU寄存器</td><td>块</td><td>函数调用</td><td>优化速度的提示</td></tr><tr><td><code>static</code></td><td>静态内存</td><td>块/文件</td><td>节目</td><td>保值</td></tr><tr><td><code>extern</code></td><td>静态内存</td><td>全球</td><td>节目</td><td>在别处声明</td></tr></tbody></table><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>这是一个完整的程序，显示了实际的范围和生命周期：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int global_var = 10; // global scope</span></span>
<span class="line"><span>void demo_scope(void) {</span></span>
<span class="line"><span>    int local_var = 5; // block scope</span></span>
<span class="line"><span>    static int persistent = 0; // retains value between calls</span></span>
<span class="line"><span>    printf(&quot;Global: %d, Local: %d, Static: %d\\n&quot;, global_var, local_var, persistent);</span></span>
<span class="line"><span>    persistent++;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;First call:\\n&quot;);</span></span>
<span class="line"><span>    demo_scope();</span></span>
<span class="line"><span>    printf(&quot;\\nSecond call:\\n&quot;);</span></span>
<span class="line"><span>    demo_scope();</span></span>
<span class="line"><span>    printf(&quot;\\nAccessing global variable in main: %d\\n&quot;, global_var);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc scope_demo.c -o scope_demo</span></span>
<span class="line"><span>./scope_demo</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一次通话：</span></span>
<span class="line"><span>全局：10，本地：5，静态：0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二次通话：</span></span>
<span class="line"><span>全局：10，本地：5，静态：1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>访问 main 中的全局变量：10</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>范围和生命周期是代码下面不可见的结构。它们定义了哪些数据在何处可用以及可用时长。如果不理解它们，您将面临以下错误：</p><ul><li>函数返回后未初始化的值</li><li>变量神秘重置</li><li>本地名称和全局名称之间的冲突</li></ul><p>一旦了解编译器如何管理变量，您就可以自信地推断内存、性能和正确性。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个带有静态计数器的函数并调用它3次。观察计数如何持续。</li><li>添加一个全局变量，从两个不同的函数修改它，并打印结果。</li><li>创建具有相同名称的变量的嵌套块，查看阴影的行为方式。</li><li>将变量移出函数并对其进行标记<code>static</code>。尝试从另一个函数访问它，会发生什么？</li><li>使用全局变量和局部变量重写之前的“计算器”示例以查看差异。</li></ol><p>当您了解作用域和生命周期时，您就可以控制程序的数据如何移动、生存和消亡，这是每个真正的 C 程序员都需要的技能。</p>`,38)])])}const b=s(t,[["render",i]]);export{u as __pageData,b as default};
